-- bloodLink donor network, phase 2: requests in shadow mode (docs/PLANS/plan_donor_network.md,
-- "Matching logic" and "Phase 2 build spec"). A request runs real waves and records who
-- would be asked, but nobody is told and nobody answers: every response stays 'notified'.
--
-- * blood_compatibility      the rules of donorGroupsFor() in src/lib/compatibility.js as rows
--                            (generated by scripts/make-compatibility-rows.mjs; the check
--                            script compares them with the function again)
-- * blood_requests           one row per request, with its anchor point and the travel
--                            conditions it was raised under
-- * request_waves            one row per wave sent: sizes and counts, never a donor
-- * request_responses        one row per donor asked, written only by match_wave()
-- * create_request()         a member of an approved organization raises a request
-- * cancel_request()         a member of the raising organization closes it
-- * match_wave()             one wave, as in Step 3; internal only
-- * advance_requests()       the next wave of each request that is due, then each request's
--                            status by Step 4; internal only, run by the cron job
-- * request_wave_summary()   the waves of one request, for its organization and admins
-- * schedule_donor_requests() and unschedule_donor_requests() add and remove the one-minute
--                            cron job; this migration schedules nothing
--
-- Donors see none of it. Shadow asks never touch donor_status: the 72 hour gap, the weekly
-- limit and `rested` read the donor's asks from request_responses of requests in the same
-- mode. match_wave() follows src/lib/donorMatching.js (planWave); the tie-break key is the md5
-- one of S10, the distance is ST_Distance / 1000 (S11), and one advisory lock lets only one
-- wave run at a time (S12).

-- ── blood_compatibility ──────────────────────────────────────────────────────

create table public.blood_compatibility (
  recipient_code text not null check (recipient_code ~ '^[0-9]{1,3}$'),
  component_category text not null
    check (component_category in ('whole_blood', 'red_cells', 'plasma', 'platelets')),
  donor_code text not null check (donor_code ~ '^[0-9]{1,3}$'),
  primary key (recipient_code, component_category, donor_code)
);

