-- eRaktKosh component code to compatibility category, as COMPONENT_CATEGORIES in
-- src/lib/compatibility.js. Null for a code that has none.
create or replace function public.component_category(p_component_code text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_component_code
    when '11' then 'whole_blood'
    when '12' then 'red_cells'
    when '28' then 'red_cells'
    when '29' then 'red_cells'
    when '30' then 'red_cells'
    when '13' then 'plasma'
    when '17' then 'plasma'
    when '18' then 'plasma'
    when '19' then 'plasma'
    when '21' then 'plasma'
    when '14' then 'platelets'
    when '16' then 'platelets'
    when '20' then 'platelets'
    when '23' then 'platelets'
  end;
$$;

-- Step 3's defaults, as WAVE_SETTINGS in src/lib/donorMatching.js: minutes between waves,
-- most waves, most donors per wave, overbooking and the fewest donors a wave asks.
create or replace function public.donor_wave_settings(p_urgency text)
returns table (gap_minutes integer, max_waves integer, cap integer, overbook numeric, min_donors integer)
language sql
immutable
set search_path = ''
as $$
  select w.gap_minutes, w.max_waves, w.cap, w.overbook, w.min_donors
  from (values
    ('critical', 10, 6, 40, 1.5, 3),
    ('urgent', 30, 4, 25, 1.5, 3),
    ('routine', 240, 3, 25, 1.3, 3)
  ) as w (urgency, gap_minutes, max_waves, cap, overbook, min_donors)
  where w.urgency = p_urgency;
$$;

-- ── blood_requests ───────────────────────────────────────────────────────────

create table public.blood_requests (
  id bigint generated always as identity primary key,
  kind text not null check (kind in ('shortfall', 'apheresis')),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  anchor_hospital_code text not null references public.blood_banks (hospital_code),
  anchor_point extensions.geography(Point, 4326) not null,
  blood_group_code text not null check (blood_group_code ~ '^[0-9]{1,3}$'),
  component_id text not null check (component_id ~ '^[0-9]{1,3}$'),
  units_needed integer not null check (units_needed between 1 and 50),
  urgency text not null check (urgency in ('critical', 'urgent', 'routine')),
  needed_by timestamptz not null,
  allow_compatible boolean not null default false,
  patient_reference text
    check (char_length(patient_reference) between 1 and 40 and patient_reference !~ '[[:cntrl:]]'),
  -- The travel conditions at creation; the bounds are TRAVEL_BOUNDS in src/lib/donorRequests.js.
  zone_free_flow_kmh double precision not null check (zone_free_flow_kmh between 5 and 120),
  congestion_percent double precision not null check (congestion_percent between 0 and 200),
  rain_factor double precision not null check (rain_factor between 1 and 1.3),
  mode text not null default 'shadow' check (mode in ('shadow')),
  area text not null check (area in ('urban', 'rural')),
  status text not null default 'open'
    check (status in ('open', 'covered', 'fulfilled', 'partly_fulfilled', 'expired', 'cancelled')),
  waves_sent smallint not null default 0 check (waves_sent between 0 and 6),
  next_wave_at timestamptz not null default now(),
  units_donated integer not null default 0 check (units_donated >= 0),
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  closed_at timestamptz,
  close_reason text check (char_length(close_reason) between 1 and 200),
  -- A request is closed exactly when its status is final.
  check ((status in ('open', 'covered')) = (closed_at is null))
);
create index blood_requests_due_idx
  on public.blood_requests (next_wave_at)
  where status in ('open', 'covered');
create index blood_requests_organization_idx
  on public.blood_requests (organization_id, created_at desc);

-- A donation keeps existing when its request goes.
alter table public.donations
  add constraint donations_request_id_fkey
  foreign key (request_id) references public.blood_requests (id) on delete set null;

-- ── request_waves ────────────────────────────────────────────────────────────

-- What staff judge in shadow mode, without seeing donors. The counts, bands and scores are
-- over the donors the wave asked. filter_counts holds, for each hard filter, how many donors
-- with an area inside the request's widest ring it removed; a donor failing several filters
-- is counted in each.
create table public.request_waves (
  request_id bigint not null references public.blood_requests (id) on delete cascade,
  wave smallint not null check (wave between 1 and 6),
  ring_km integer not null,
  candidate_count integer not null check (candidate_count >= 0),
  p_accept double precision not null check (p_accept > 0),
  k integer not null check (k >= 0),
  filter_counts jsonb not null,
  exact_count integer not null check (exact_count >= 0),
  compatible_count integer not null check (compatible_count >= 0),
  -- Donors asked, counted by the distance to the anchor: to 5, 10, 15, 25 km, beyond.
  distance_bands jsonb not null,
  score_min double precision,
  score_median double precision,
  score_max double precision,
  ran_at timestamptz not null default now(),
  primary key (request_id, wave)
);

-- ── request_responses ────────────────────────────────────────────────────────

create table public.request_responses (
  id bigint generated always as identity primary key,
  request_id bigint not null references public.blood_requests (id) on delete cascade,
  donor_id uuid not null references public.profiles (id) on delete cascade,
  wave smallint not null check (wave between 1 and 6),
  score double precision not null check (score >= 0),
  est_minutes double precision not null check (est_minutes >= 0),
  is_exact_group boolean not null,
  status text not null default 'notified'
    check (status in ('notified', 'seen', 'accepted', 'declined', 'expired', 'not_needed',
                      'cancelled', 'no_show', 'arrived', 'donated', 'deferred')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (request_id, donor_id)
);
-- The 72 hour gap, the weekly limit and `rested` read a donor's recent asks.
create index request_responses_donor_idx on public.request_responses (donor_id, created_at desc);

create trigger request_responses_set_updated_at
  before update on public.request_responses
  for each row execute function public.set_updated_at();

-- ── row-level security ───────────────────────────────────────────────────────

alter table public.blood_compatibility enable row level security;
alter table public.blood_requests enable row level security;
alter table public.request_waves enable row level security;
alter table public.request_responses enable row level security;

-- Donors have no policy on any of them. Members of the raising organization read its
-- requests and waves; admins read everything, responses included. Writes go only through
-- the functions below.
create policy blood_requests_select_organization on public.blood_requests
  for select to authenticated
  using (exists (
    select 1 from public.profiles p
    where p.id = (select auth.uid()) and p.organization_id = blood_requests.organization_id
  ));
create policy blood_requests_select_admin on public.blood_requests
  for select to authenticated using ((select public.is_admin()));

create policy request_waves_select_organization on public.request_waves
  for select to authenticated
  using (exists (
    select 1
    from public.blood_requests r
    join public.profiles p on p.organization_id = r.organization_id
    where r.id = request_waves.request_id and p.id = (select auth.uid())
  ));
create policy request_waves_select_admin on public.request_waves
  for select to authenticated using ((select public.is_admin()));

create policy request_responses_select_admin on public.request_responses
  for select to authenticated using ((select public.is_admin()));

-- ── grants (explicit, so the "expose new tables" setting doesn't matter) ─────

revoke all on public.blood_compatibility, public.blood_requests, public.request_waves,
  public.request_responses from public, anon, authenticated;

grant select on public.blood_requests to authenticated;
grant select on public.request_waves to authenticated;
grant select on public.request_responses to authenticated;
-- blood_compatibility is read only by the functions below.

-- ── match_wave ───────────────────────────────────────────────────────────────

-- One wave of one request, as in Step 3 and planWave() in src/lib/donorMatching.js.
-- Records the wave, asks the top k donors (their responses stay 'notified' in shadow mode)
-- and sets the time of the next wave. Returns how many donors were asked; 0 when the request
-- is closed, past its last wave or already covered. A wave with no candidates is still
-- recorded, so the next one widens the ring.
-- Internal: create_request() and advance_requests() call it.
create or replace function public.match_wave(p_request_id bigint)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_req public.blood_requests;
  v_set record;
  v_wave integer;
  v_wanted integer;
  v_ring integer;
  v_widest integer;
  v_groups text[];
  v_today date := (now() at time zone 'Asia/Kolkata')::date;
  v_needed_date date;
  v_minute time := date_trunc('minute', now() at time zone 'Asia/Kolkata')::time;
  v_tau double precision;
  v_asked integer;
begin
  perform pg_advisory_xact_lock(hashtext('bloodlink.match_wave'));

  select * into v_req from public.blood_requests where id = p_request_id for update;
  if not found then
    raise exception 'No such request' using errcode = 'P0002';
  end if;
  if v_req.status not in ('open', 'covered') then
    return 0;
  end if;

  select * into v_set from public.donor_wave_settings(v_req.urgency);
  v_wave := v_req.waves_sent + 1;
  if v_wave > v_set.max_waves then
    return 0;
  end if;

  -- Acceptances wanted: ceil(units left x overbook) less those still on hold. The rounding
  -- to 9 places is ceilClean() in donorMatching.js.
  v_wanted := ceil(round(greatest(v_req.units_needed - v_req.units_donated, 0) * v_set.overbook, 9))::integer
    - (select count(*) from public.request_responses r
       where r.request_id = v_req.id and r.status in ('accepted', 'arrived'));
  if v_wanted <= 0 then
    return 0;
  end if;

  -- Urban 5, 10, 15, 25 km and rural 20, 50, 100, 150 km; later waves reuse the widest.
  v_ring := (case when v_req.area = 'rural' then array[20, 50, 100, 150] else array[5, 10, 15, 25] end)
    [least(v_wave, 4)];
  v_widest := (case when v_req.area = 'rural' then 150 else 25 end);

  -- Groups to ask: the request's own, plus compatible ones from the third wave when allowed.
  if v_req.allow_compatible and v_wave >= 3 then
    select array_agg(c.donor_code) into v_groups
    from public.blood_compatibility c
    where c.recipient_code = v_req.blood_group_code
      and c.component_category = public.component_category(v_req.component_id);
  end if;
  v_groups := coalesce(v_groups, array[v_req.blood_group_code]);

  v_needed_date := (v_req.needed_by at time zone 'Asia/Kolkata')::date;
  v_tau := case v_req.urgency when 'critical' then 30 when 'urgent' then 45 else 60 end;

  with areas as (
    -- Every area inside the widest ring, by the spatial index; km is the exact distance.
    select a.user_id, extensions.st_distance(a.cell, v_req.anchor_point) / 1000.0 as km
    from public.donor_areas a
    where extensions.st_dwithin(a.cell, v_req.anchor_point, v_widest * 1000.0)
  ),
  nearest as (
    -- The nearest area inside this wave's ring (null when none is).
    select ar.user_id, min(ar.km) filter (where ar.km <= v_ring) as km
    from areas ar
    group by ar.user_id
  ),
  pop as (
    select ds.user_id, ds.blood_group_code, ds.is_in_network, ds.eligible_from, ds.eligible_until,
           ds.needs_staff_check, ds.screening_confirmed_at,
           ds.asks_total, ds.accepts_total, ds.shows_total,
           s.is_available, s.snoozed_until,
           coalesce(s.quiet_start, time '22:00') as quiet_start,
           coalesce(s.quiet_end, time '07:00') as quiet_end,
           s.critical_overrides_quiet, s.critical_overrides_gap, s.max_requests_per_week,
           s.apheresis_willing,
           n.km as nearest_km,
           h.last_asked, h.asks_7d
    from nearest n
    join public.donor_status ds on ds.user_id = n.user_id
    left join public.donor_settings s on s.user_id = ds.user_id
    left join lateral (
      -- Asks in requests of the same mode (S3), not the donor's live counters.
      select max(r.created_at) as last_asked,
             count(*) filter (where r.created_at > now() - interval '7 days') as asks_7d
      from public.request_responses r
      join public.blood_requests b on b.id = r.request_id
      where r.donor_id = ds.user_id and b.mode = v_req.mode
    ) h on true
  ),
  flagged as (
    -- One flag per hard filter of Step 1; true means the donor fails it.
    select p.*,
      not p.is_in_network as f1,
      (p.is_available is not true or coalesce(p.snoozed_until > now(), false)) as f2,
      (p.blood_group_code is null or not (p.blood_group_code = any (v_groups))) as f3,
      (p.eligible_from is null or p.eligible_until is null
        or p.eligible_from > v_needed_date or p.eligible_until < v_today) as f4,
      (p.screening_confirmed_at is null
        or v_today - (p.screening_confirmed_at at time zone 'Asia/Kolkata')::date > 90) as f5,
      p.needs_staff_check as f6,
      (v_req.kind = 'apheresis' and p.apheresis_willing is not true) as f7,
      (p.nearest_km is null) as f8,
      (not ((v_req.urgency = 'critical' and p.critical_overrides_gap is true)
            or p.last_asked is null or now() - p.last_asked > interval '72 hours')
        or p.asks_7d >= coalesce(p.max_requests_per_week, 2)) as f9,
      (not (v_req.urgency = 'critical' and p.critical_overrides_quiet is true)
        and case
          when p.quiet_start = p.quiet_end then false
          when p.quiet_start < p.quiet_end then v_minute >= p.quiet_start and v_minute < p.quiet_end
          else v_minute >= p.quiet_start or v_minute < p.quiet_end
        end) as f10,
      exists (select 1 from public.request_responses r
              where r.request_id = v_req.id and r.donor_id = p.user_id) as f11,
      (p.user_id is not distinct from v_req.created_by) as f12
    from pop p
  ),
  counts as (
    select jsonb_build_object(
      'not_in_network', count(*) filter (where f1),
      'unavailable_or_snoozed', count(*) filter (where f2),
      'group', count(*) filter (where f3),
      'not_eligible_in_time', count(*) filter (where f4),
      'screening_not_confirmed', count(*) filter (where f5),
      'staff_check_pending', count(*) filter (where f6),
      'not_apheresis_willing', count(*) filter (where f7),
      'outside_ring', count(*) filter (where f8),
      'asked_too_often', count(*) filter (where f9),
      'quiet_hours', count(*) filter (where f10),
      'already_asked', count(*) filter (where f11),
      'the_raiser', count(*) filter (where f12)
    ) as filter_counts
    from flagged
  ),
  timed as (
    select f.*,
           -- km x detour factor / free-flow speed x 60 x (1 + congestion) x rain, as
           -- travelMinutes in src/lib/trafficModel.js.
           f.nearest_km * 1.34 / v_req.zone_free_flow_kmh * 60
             * (1 + v_req.congestion_percent / 100) * v_req.rain_factor as minutes,
           (f.blood_group_code = v_req.blood_group_code) as is_exact
    from flagged f
    where not (f.f1 or f.f2 or f.f3 or f.f4 or f.f5 or f.f6 or f.f7 or f.f8 or f.f9 or f.f10
               or f.f11 or f.f12)
  ),
  scored as (
    select t.user_id, t.nearest_km, t.minutes, t.is_exact,
           (t.accepts_total + 1)::double precision / (t.asks_total + 5) as respond,
           -- score = p_donate x e^(-minutes / tau) x rested x groupFit
           (t.accepts_total + 1)::double precision / (t.asks_total + 5)
             * ((t.shows_total + 4)::double precision / (t.accepts_total + 5))
             * exp(-t.minutes / v_tau)
             * (case when t.last_asked is null then 1::double precision
                     else least(1::double precision,
                                0.5 + greatest(0::double precision,
                                               extract(epoch from now() - t.last_asked)::double precision / 86400)
                                      / 28) end)
             * (case when t.is_exact then 1::double precision else 0.7::double precision end) as score,
           -- The tie-break of S10: the first 8 hex digits of md5(request:donor) as a
           -- fraction of 2^32.
           ('x' || substr(md5(v_req.id::text || ':' || t.user_id::text), 1, 8))::bit(32)::bigint
             / 4294967296.0 as tie_key
    from timed t
  ),
  ranked as (
    select s.*, row_number() over (order by s.score desc, s.tie_key, s.user_id) as rn
    from scored s
  ),
  sized as (
    -- p_accept: the mean `respond` of the top min(cap, candidates), the prior when none.
    -- k: ceil(wanted / p_accept) clamped to [minimum, cap], then to the candidates there are.
    select z.n, z.p_accept,
           least(
             least(greatest(ceil(round((v_wanted / z.p_accept)::numeric, 9))::integer, v_set.min_donors),
                   v_set.cap),
             z.n) as k
    from (
      select (select count(*) from ranked)::integer as n,
             coalesce((select avg(r.respond) from ranked r where r.rn <= v_set.cap), 1.0 / 5) as p_accept
    ) z
  ),
  asked as (
    select r.* from ranked r join sized z on r.rn <= z.k
  ),
  inserted as (
    insert into public.request_responses (request_id, donor_id, wave, score, est_minutes, is_exact_group)
    select v_req.id, a.user_id, v_wave, a.score, a.minutes, a.is_exact from asked a order by a.rn
    returning 1
  ),
  stats as (
    select count(*) filter (where a.is_exact)::integer as exact_count,
           count(*) filter (where not a.is_exact)::integer as compatible_count,
           jsonb_build_array(
             count(*) filter (where a.nearest_km <= 5),
             count(*) filter (where a.nearest_km > 5 and a.nearest_km <= 10),
             count(*) filter (where a.nearest_km > 10 and a.nearest_km <= 15),
             count(*) filter (where a.nearest_km > 15 and a.nearest_km <= 25),
             count(*) filter (where a.nearest_km > 25)) as bands,
           min(a.score) as score_min,
           percentile_cont(0.5) within group (order by a.score) as score_median,
           max(a.score) as score_max
    from asked a
  )
  insert into public.request_waves
    (request_id, wave, ring_km, candidate_count, p_accept, k, filter_counts, exact_count,
     compatible_count, distance_bands, score_min, score_median, score_max)
  select v_req.id, v_wave, v_ring, z.n, z.p_accept, z.k, (select c.filter_counts from counts c),
         st.exact_count, st.compatible_count, st.bands, st.score_min, st.score_median, st.score_max
  from sized z
  cross join stats st
  returning k into v_asked;

  update public.blood_requests
  set waves_sent = v_wave,
      next_wave_at = now() + make_interval(mins => v_set.gap_minutes)
  where id = v_req.id;

  return v_asked;
end;
$$;

-- ── create_request ───────────────────────────────────────────────────────────

-- A member of an approved, unsuspended organization raises a shadow request. The anchor is
-- a blood bank's eRaktKosh code; its position is the accepted bank_location_fixes row, else
-- the directory's own point when it is usable (S6). The area is urban when more than 10
-- banks with a usable position lie within 15 km, as /api/blood-search counts (S7). The
-- travel conditions come from the route (S8) and are only bounds-checked here. Critical and
-- urgent requests run their first wave at once; a routine request waits for the next 09:00
-- to 20:00 India window and the cron job sends it (S13). Returns the request's id.
create or replace function public.create_request(
  p_anchor_hospital_code text,
  p_blood_group_code text,
  p_component_code text,
  p_units_needed integer,
  p_urgency text,
  p_needed_by timestamptz,
  p_allow_compatible boolean,
  p_patient_reference text,
  p_kind text,
  p_zone_free_flow_kmh numeric,
  p_congestion_percent numeric,
  p_rain_factor numeric
)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_org public.organizations;
  v_point extensions.geography;
  v_banks integer;
  v_area text;
  v_reference text := nullif(btrim(p_patient_reference), '');
  v_ist timestamp := now() at time zone 'Asia/Kolkata';
  v_first_wave timestamptz := now();
  v_id bigint;
begin
  if v_user is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('bloodlink.match_wave'));

  -- S5: the approved applicant of an approved organization, not suspended.
  select o.* into v_org
  from public.profiles p
  join public.organizations o on o.id = p.organization_id
  where p.id = v_user and o.status = 'approved' and not p.is_suspended;
  if not found then
    raise exception 'Only a member of an approved organization can raise a request'
      using errcode = '42501';
  end if;
  if (select count(*) from public.blood_requests r
      where r.organization_id = v_org.id and r.status in ('open', 'covered')) >= 10 then
    raise exception 'Your organization already has 10 open requests' using errcode = '22023';
  end if;
  if (select count(*) from public.blood_requests r
      where r.organization_id = v_org.id
        and (r.created_at at time zone 'Asia/Kolkata')::date = v_ist::date) >= 20 then
    raise exception 'Your organization has raised 20 requests today' using errcode = '22023';
  end if;

  -- The same rules as sanitizeRequest() in src/lib/donorRequests.js.
  if p_kind is null or p_kind not in ('shortfall', 'apheresis') then
    raise exception 'Choose shortfall or apheresis' using errcode = '22023';
  end if;
  if p_urgency is null or p_urgency not in ('critical', 'urgent', 'routine') then
    raise exception 'Choose critical, urgent or routine' using errcode = '22023';
  end if;
  if p_units_needed is null or p_units_needed not between 1 and 50 then
    raise exception 'Units needed must be from 1 to 50' using errcode = '22023';
  end if;
  if p_blood_group_code is null
     or not exists (select 1 from public.blood_compatibility c where c.recipient_code = p_blood_group_code) then
    raise exception 'Unknown blood group' using errcode = '22023';
  end if;
  if public.component_category(p_component_code) is null then
    raise exception 'Unknown component' using errcode = '22023';
  end if;
  if p_needed_by is null or p_needed_by < now() + interval '30 minutes'
     or p_needed_by > now() + interval '14 days' then
    raise exception 'The blood must be needed between 30 minutes and 14 days from now'
      using errcode = '22023';
  end if;
  if coalesce(p_allow_compatible, false) and v_org.kind <> 'blood_bank' then
    raise exception 'Only a blood bank may accept compatible groups' using errcode = '42501';
  end if;
  if v_reference is not null
     and (char_length(v_reference) > 40 or v_reference ~ '[[:cntrl:]]') then
    raise exception 'The patient reference must be at most 40 characters' using errcode = '22023';
  end if;
  if p_zone_free_flow_kmh is null or p_zone_free_flow_kmh not between 5 and 120
     or p_congestion_percent is null or p_congestion_percent not between 0 and 200
     or p_rain_factor is null or p_rain_factor not between 1 and 1.3 then
    raise exception 'The travel conditions are out of range' using errcode = '22023';
  end if;

  -- S6: the anchor's position.
  if not exists (select 1 from public.blood_banks b where b.hospital_code = p_anchor_hospital_code) then
    raise exception 'No blood bank has that eRaktKosh code' using errcode = 'P0002';
  end if;
  select coalesce(
    (select f.location from public.bank_location_fixes f
     where f.hospital_code = p_anchor_hospital_code and f.status = 'accepted'),
    (select b.location from public.blood_banks b
     where b.hospital_code = p_anchor_hospital_code and b.location_quality = 'ok')
  ) into v_point;
  if v_point is null then
    raise exception 'bloodLink has no usable position for that blood bank' using errcode = '22023';
  end if;

  -- S7: banks with a usable position within 15 km, the anchor included.
  select count(*) into v_banks
  from (
    select b.hospital_code
    from public.blood_banks b
    where b.location_quality = 'ok'
      and extensions.st_dwithin(b.location, v_point, 15000)
      and not exists (select 1 from public.bank_location_fixes f
                      where f.hospital_code = b.hospital_code and f.status = 'accepted')
    union all
    select f.hospital_code
    from public.bank_location_fixes f
    where f.status = 'accepted' and extensions.st_dwithin(f.location, v_point, 15000)
  ) banks;
  v_area := case when v_banks > 10 then 'urban' else 'rural' end;

  -- S13: a routine request's first wave waits for the 09:00 to 20:00 India window.
  if p_urgency = 'routine' then
    if v_ist::time < time '09:00' then
      v_first_wave := (date_trunc('day', v_ist) + interval '9 hours') at time zone 'Asia/Kolkata';
    elsif v_ist::time >= time '20:00' then
      v_first_wave := (date_trunc('day', v_ist) + interval '1 day 9 hours') at time zone 'Asia/Kolkata';
    end if;
  end if;

  insert into public.blood_requests
    (kind, organization_id, anchor_hospital_code, anchor_point, blood_group_code, component_id,
     units_needed, urgency, needed_by, allow_compatible, patient_reference,
     zone_free_flow_kmh, congestion_percent, rain_factor, area, next_wave_at, created_by)
  values
    (p_kind, v_org.id, p_anchor_hospital_code, v_point, p_blood_group_code, p_component_code,
     p_units_needed, p_urgency, p_needed_by, coalesce(p_allow_compatible, false), v_reference,
     p_zone_free_flow_kmh, p_congestion_percent, p_rain_factor, v_area, v_first_wave, v_user)
  returning id into v_id;

  if p_urgency <> 'routine' then
    perform public.match_wave(v_id);
  end if;
  return v_id;
end;
$$;

-- ── cancel_request ───────────────────────────────────────────────────────────

-- A member of the raising organization closes an open or covered request as cancelled.
create or replace function public.cancel_request(p_request_id bigint, p_reason text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := auth.uid();
  v_reason text := btrim(p_reason);
  v_req public.blood_requests;
begin
  if v_user is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if v_reason is null or char_length(v_reason) not between 1 and 200 then
    raise exception 'Give a reason of 1 to 200 characters' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtext('bloodlink.match_wave'));

  select * into v_req from public.blood_requests where id = p_request_id for update;
  if not found then
    raise exception 'No such request' using errcode = 'P0002';
  end if;
  if not exists (
    select 1 from public.profiles p
    where p.id = v_user and p.organization_id = v_req.organization_id
  ) then
    raise exception 'Only a member of the raising organization can cancel a request'
      using errcode = '42501';
  end if;
  if v_req.status not in ('open', 'covered') then
    raise exception 'The request is already closed' using errcode = '22023';
  end if;

  update public.blood_requests
  set status = 'cancelled', closed_at = now(), close_reason = v_reason
  where id = v_req.id;
end;
$$;

-- ── advance_requests ─────────────────────────────────────────────────────────

-- Run each minute by the cron job. Every open or covered request whose next_wave_at has
-- come gets its next wave; then every open or covered request gets its status by Step 4 and
-- nextRequestStatus() in src/lib/donorMatching.js: fulfilled when no units are left, the end
-- state at needed_by, covered when the acceptances on hold reach the target, the end state
-- once the last wave is done and its gap has passed, else open. The end state is
-- partly_fulfilled when any units were donated, else expired. In shadow mode nobody answers,
-- so nothing is on hold and no response changes. Returns how many donors the waves asked.
create or replace function public.advance_requests()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id bigint;
  v_req public.blood_requests;
  v_set record;
  v_left integer;
  v_on_hold integer;
  v_end_state text;
  v_status text;
  v_reason text;
  v_asked integer := 0;
begin
  perform pg_advisory_xact_lock(hashtext('bloodlink.match_wave'));

  for v_id in
    select r.id from public.blood_requests r where r.status in ('open', 'covered') order by r.id
  loop
    select * into v_req from public.blood_requests where id = v_id for update;
    if v_req.next_wave_at <= now() and now() < v_req.needed_by then
      v_asked := v_asked + public.match_wave(v_id);
      select * into v_req from public.blood_requests where id = v_id;
    end if;

    select * into v_set from public.donor_wave_settings(v_req.urgency);
    v_left := v_req.units_needed - v_req.units_donated;
    v_on_hold := (select count(*) from public.request_responses r
                  where r.request_id = v_id and r.status in ('accepted', 'arrived'));
    v_end_state := case when v_req.units_donated > 0 then 'partly_fulfilled' else 'expired' end;

    if v_left <= 0 then
      v_status := 'fulfilled';
      v_reason := 'Units donated';
    elsif now() >= v_req.needed_by then
      v_status := v_end_state;
      v_reason := 'Needed-by time reached';
    elsif v_on_hold >= ceil(round(v_left * v_set.overbook, 9)) then
      v_status := 'covered';
    elsif v_req.waves_sent >= v_set.max_waves and now() >= v_req.next_wave_at then
      v_status := v_end_state;
      v_reason := 'All waves sent';
    else
      v_status := 'open';
    end if;

    if v_status <> v_req.status then
      update public.blood_requests
      set status = v_status,
          closed_at = case when v_status in ('open', 'covered') then null else now() end,
          close_reason = case when v_status in ('open', 'covered') then null else v_reason end
      where id = v_id;
    end if;
  end loop;

  return v_asked;
end;
$$;

-- ── request_wave_summary ─────────────────────────────────────────────────────

-- The waves of one request, for members of the raising organization and admins: the ring,
-- candidates, size, acceptance estimate, the exact and compatible donors asked, their
-- distance bands and score range, and what each hard filter removed. Never a donor's
-- identity or position.
create or replace function public.request_wave_summary(p_request_id bigint)
returns table (
  wave integer,
  ring_km integer,
  candidate_count integer,
  k integer,
  p_accept double precision,
  exact_count integer,
  compatible_count integer,
  distance_bands jsonb,
  score_min double precision,
  score_median double precision,
  score_max double precision,
  filter_counts jsonb,
  ran_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_user uuid := auth.uid();
  v_organization_id uuid;
begin
  if v_user is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  select r.organization_id into v_organization_id
  from public.blood_requests r where r.id = p_request_id;
  if not found then
    raise exception 'No such request' using errcode = 'P0002';
  end if;
  if not public.is_admin() and not exists (
    select 1 from public.profiles p
    where p.id = v_user and p.organization_id = v_organization_id
  ) then
    raise exception 'Only the raising organization and admins can see a request''s waves'
      using errcode = '42501';
  end if;

  return query
  select w.wave::integer, w.ring_km, w.candidate_count, w.k, w.p_accept, w.exact_count,
         w.compatible_count, w.distance_bands, w.score_min, w.score_median, w.score_max,
         w.filter_counts, w.ran_at
  from public.request_waves w
  where w.request_id = p_request_id
  order by w.wave;
end;
$$;

-- ── cron ─────────────────────────────────────────────────────────────────────

-- Creates or replaces the one-minute advance-requests job.
create or replace function public.schedule_donor_requests()
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
begin
  return jsonb_build_object(
    'advance-requests', cron.schedule('advance-requests', '* * * * *',
      $job$select public.advance_requests()$job$));
end;
$$;

-- Removes the job. Returns how many there were.
create or replace function public.unschedule_donor_requests()
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_name text;
  v_count integer := 0;
begin
  for v_name in
    select jobname from cron.job where jobname = 'advance-requests'
  loop
    perform cron.unschedule(v_name);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

-- ── grants ───────────────────────────────────────────────────────────────────

-- Internal: matching and the cron job (run as postgres) only.
revoke execute on function public.match_wave(bigint),
  public.advance_requests(),
  public.donor_wave_settings(text),
  public.component_category(text)
  from public, anon, authenticated;
revoke execute on function public.schedule_donor_requests(),
  public.unschedule_donor_requests()
  from public, anon, authenticated, service_role;

revoke execute on function public.create_request(text, text, text, integer, text, timestamptz,
    boolean, text, text, numeric, numeric, numeric),
  public.cancel_request(bigint, text),
  public.request_wave_summary(bigint)
  from public, anon;
grant execute on function public.create_request(text, text, text, integer, text, timestamptz,
    boolean, text, text, numeric, numeric, numeric),
  public.cancel_request(bigint, text),
  public.request_wave_summary(bigint)
  to authenticated;
